import{_ as i,o as a,c as t,aj as e}from"./framework.js";const c=JSON.parse('{"title":"部署 Git 产物 | Cli / Workflows | Documentation","description":"kb deploy 用于发布已经提交到 Git 的 Kooboo 资源产物。它对比“上一次成功部署的 commit”和“本次候选 commit”，生成完整计划，在一个 CLI 进程中执行上传、删除和远端校验，并输出部署回执。","frontmatter":{"title":"部署 Git 产物 | Cli / Workflows | Documentation","description":"kb deploy 用于发布已经提交到 Git 的 Kooboo 资源产物。它对比“上一次成功部署的 commit”和“本次候选 commit”，生成完整计划，在一个 CLI 进程中执行上传、删除和远端校验，并输出部署回执。","head":[["link",{"rel":"canonical","href":"https://docs.kooboo.com/zh/cli/workflows/deploy.html"}]]},"headers":[],"relativePath":"zh/cli/workflows/deploy.md","filePath":"cli/workflows/deploy.md","lastUpdated":1787220900000}'),l={name:"zh/cli/workflows/deploy.md"};function n(h,s,p,d,o,k){return a(),t("div",null,[...s[0]||(s[0]=[e(`<h1 id="部署-git-产物" tabindex="-1">部署 Git 产物 <a class="header-anchor" href="#部署-git-产物" aria-label="Permalink to &quot;部署 Git 产物&quot;">​</a></h1><p><code>kb deploy</code> 用于发布已经提交到 Git 的 Kooboo 资源产物。它对比“上一次成功部署的 commit”和“本次候选 commit”，生成完整计划，在一个 CLI 进程中执行上传、删除和远端校验，并输出部署回执。</p><p>与 <code>kb push --git --commit</code> 相比，<code>kb deploy</code> 面向正式发布：它处理一个明确的 commit 范围，删除需要单独批准，任一写入或校验失败都会返回非零退出码。</p><p>正式发布中的删除也应由 <code>deploy</code> 完成。<code>deploy</code> 只删除 Git 范围明确记录的资源，不会顺带清理远端额外资源；<a href="./check-and-prune.html"><code>kb prune</code></a> 仅用于发布流程之外的远端漂移审计，不能替代确定性的 Git 发布。</p><h2 id="使用前提" tabindex="-1">使用前提 <a class="header-anchor" href="#使用前提" aria-label="Permalink to &quot;使用前提&quot;">​</a></h2><p>当前目录必须是保存 Kooboo 最终资源的 Git 项目，并且候选产物已经提交。部署不会读取未提交的工作区内容。</p><p>项目根目录需要配置：</p><div class="language-ini vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">ini</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">KOOBOO_SITE_URL</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">=https://example.com</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">KOOBOO_USERNAME</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">=your-username</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">KOOBOO_PASSWORD</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">=your-password</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">KOOBOO_SITE_ID</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">=your-site-id</span></span></code></pre></div><p><code>KOOBOO_SITE_ID</code> 是可选项，但正式发布建议设置。CLI 登录后会核对实际站点 ID；不一致时不会写入远端。</p><h2 id="选择部署范围" tabindex="-1">选择部署范围 <a class="header-anchor" href="#选择部署范围" aria-label="Permalink to &quot;选择部署范围&quot;">​</a></h2><p>准备两个 Git commit：</p><ul><li><code>from</code>：最后一次收到成功部署回执的产物 commit；</li><li><code>to</code>：本次准备发布的候选产物 commit。</li></ul><p>两者不要求是父子关系。CLI 会解析为完整、不可变的 commit ID，并计算整个 <code>from → to</code> 范围中的新增、修改、删除和重命名。</p><h2 id="先生成并审查计划" tabindex="-1">先生成并审查计划 <a class="header-anchor" href="#先生成并审查计划" aria-label="Permalink to &quot;先生成并审查计划&quot;">​</a></h2><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">kb</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> deploy</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> \\</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  --from</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> &lt;</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">last-successful-commi</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">t</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">&gt;</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> \\</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  --to</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> &lt;</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">candidate-commi</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">t</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">&gt;</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> \\</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  --dry-run</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> \\</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  --write-plan</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> .kooboo/deploy-plan.json</span></span></code></pre></div><p>Dry run 不登录站点，也不写远端。输出会列出：</p><ul><li>需要新增或更新的资源数；</li><li>需要删除的资源数；</li><li>因不是 Kooboo 资源或匹配 <code>.pushignore</code> 而跳过的文件；</li><li>用于确认计划内容未被改动的 digest。</li></ul><p>计划中的资源内容取自候选 commit，而不是当前工作区。候选 commit 中的 <code>.pushignore</code> 决定哪些 Git 变化被跳过。</p><h2 id="执行部署" tabindex="-1">执行部署 <a class="header-anchor" href="#执行部署" aria-label="Permalink to &quot;执行部署&quot;">​</a></h2><p>计划不包含删除时：</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">kb</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> deploy</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> \\</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  --from</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> &lt;</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">last-successful-commi</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">t</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">&gt;</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> \\</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  --to</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> &lt;</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">candidate-commi</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">t</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">&gt;</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> \\</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  --output</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> .kooboo/deploy-receipt.json</span></span></code></pre></div><p>计划包含删除时，必须在审查后显式批准：</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">kb</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> deploy</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> \\</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  --from</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> &lt;</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">last-successful-commi</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">t</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">&gt;</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> \\</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  --to</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> &lt;</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">candidate-commi</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">t</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">&gt;</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> \\</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  --apply-deletes</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> \\</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  --output</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> .kooboo/deploy-receipt.json</span></span></code></pre></div><p>没有 <code>--apply-deletes</code> 时，只要计划中存在删除，整个部署会在登录和写入前停止；CLI 不会只上传其余资源。</p><h2 id="执行已保存的计划" tabindex="-1">执行已保存的计划 <a class="header-anchor" href="#执行已保存的计划" aria-label="Permalink to &quot;执行已保存的计划&quot;">​</a></h2><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">kb</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> deploy</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> \\</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  --plan</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> .kooboo/deploy-plan.json</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> \\</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  --apply-deletes</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> \\</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  --output</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> .kooboo/deploy-receipt.json</span></span></code></pre></div><p><code>--plan</code> 不能与 <code>--from</code> 或 <code>--to</code> 同时使用。执行前，CLI 会检查计划 digest、Git commit、变更覆盖范围和候选快照内容；计划过期、缺少变化或内容不匹配时不会写入远端。</p><h2 id="执行顺序与失败规则" tabindex="-1">执行顺序与失败规则 <a class="header-anchor" href="#执行顺序与失败规则" aria-label="Permalink to &quot;执行顺序与失败规则&quot;">​</a></h2><p>CLI 按以下阶段执行：</p><ol><li>上传 Script、Style、Content File、Images、API、View 等支撑资源；</li><li>上传 Page；</li><li>执行已批准的删除。</li></ol><p>前一阶段存在失败时，后续阶段会跳过。这样可以避免 Page 先引用尚未成功上传的资源，也可以避免在上传失败后继续删除旧资源。</p><p>重复执行同一个 <code>from → to</code> 范围是允许的。计划中的远端资源已经不存在时，删除会记为 <code>already_absent</code>，不会把补偿重试判定为失败。</p><h2 id="发布后校验" tabindex="-1">发布后校验 <a class="header-anchor" href="#发布后校验" aria-label="Permalink to &quot;发布后校验&quot;">​</a></h2><p>默认情况下，写入结束后 CLI 会重新读取远端资源：</p><ul><li>对新增和修改资源比较持久化后的内容 hash；</li><li>对删除资源确认远端已经不存在。</li></ul><p>校验失败会写入回执并使命令返回非零退出码。可以用 <code>--no-verify</code> 跳过该步骤，但回执会明确标记校验未启用；此时 CLI 只能证明写入请求没有报告失败，不能证明远端内容已经对账。</p><h2 id="输出计划和回执" tabindex="-1">输出计划和回执 <a class="header-anchor" href="#输出计划和回执" aria-label="Permalink to &quot;输出计划和回执&quot;">​</a></h2><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># 终端输出 JSON</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">kb</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> deploy</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --from</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> &lt;</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">fro</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">m</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">&gt;</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --to</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> &lt;</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">t</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">o</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">&gt;</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --dry-run</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --format</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> json</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># 不打印终端正文，只写回执文件</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">kb</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> deploy</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --from</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> &lt;</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">fro</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">m</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">&gt;</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --to</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> &lt;</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">t</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">o</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">&gt;</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --format</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> silent</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> \\</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  --output</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> .kooboo/deploy-receipt.json</span></span></code></pre></div><p><code>--format</code> 支持 <code>table</code>、<code>json</code> 和 <code>silent</code>。<code>--write-plan</code> 写部署计划；<code>--output</code> 写执行回执或失败信息。两者用途不同。</p><p>成功回执包含目标站点、commit 范围、计划 digest、每个资源的执行结果和校验结果。只有 <code>success</code> 为 <code>true</code> 且进程退出码为 <code>0</code>，才能把 <code>to</code> 记录为新的成功部署基线。</p><h2 id="常用参数" tabindex="-1">常用参数 <a class="header-anchor" href="#常用参数" aria-label="Permalink to &quot;常用参数&quot;">​</a></h2><table tabindex="0"><thead><tr><th>参数</th><th>作用</th></tr></thead><tbody><tr><td><code>--from &lt;commit&gt;</code></td><td>最后一次成功部署的产物 commit</td></tr><tr><td><code>--to &lt;commit&gt;</code></td><td>本次候选产物 commit</td></tr><tr><td><code>--plan &lt;path&gt;</code></td><td>执行已保存的计划</td></tr><tr><td><code>--write-plan &lt;path&gt;</code></td><td>将校验后的计划写入 JSON 文件</td></tr><tr><td><code>--dry-run</code></td><td>只生成计划，不登录或写远端</td></tr><tr><td><code>--apply-deletes</code></td><td>批准计划中的删除操作</td></tr><tr><td><code>--no-verify</code></td><td>跳过写入后的远端校验</td></tr><tr><td><code>--format &lt;format&gt;</code></td><td>终端输出格式：<code>table</code>、<code>json</code> 或 <code>silent</code></td></tr><tr><td><code>--output &lt;path&gt;</code></td><td>将回执或失败信息写入 JSON 文件</td></tr><tr><td><code>--site-id &lt;siteId&gt;</code></td><td>指定部署时必须匹配的站点 ID</td></tr><tr><td><code>--site-url &lt;url&gt;</code></td><td>临时指定站点 URL</td></tr><tr><td><code>--username &lt;username&gt;</code></td><td>临时指定用户名</td></tr><tr><td><code>--password &lt;password&gt;</code></td><td>临时指定密码</td></tr></tbody></table><h2 id="相关文档" tabindex="-1">相关文档 <a class="header-anchor" href="#相关文档" aria-label="Permalink to &quot;相关文档&quot;">​</a></h2><ul><li><a href="./../getting-started/preparation.html">使用前准备</a></li><li><a href="./push.html">推送本地资源</a></li><li><a href="./check-and-prune.html">资源对账与远端清理</a></li><li><a href="./../troubleshooting.html">常见问题</a></li></ul>`,44)])])}const F=i(l,[["render",n]]);export{c as __pageData,F as default};
